   477→    state: &mut BeaconState<E>,
   478→    spec: &ChainSpec,
   479→) -> Result<(), Error> {
   480→    let mut lookahead = state.proposer_lookahead()?.clone().to_vec();
   481→
   482→    // Shift out proposers in the first epoch
   483→    lookahead.copy_within((E::slots_per_epoch() as usize).., 0);
   484→
   485→    let next_epoch = state
   486→        .current_epoch()
   487→        .safe_add(spec.min_seed_lookahead.as_u64())?
   488→        .safe_add(1)?;
   489→    let last_epoch_proposers = state.get_beacon_proposer_indices(next_epoch, spec)?;
   490→
   491→    // Fill in the last epoch with new proposer indices
   492→    let last_epoch_start = E::proposer_lookahead_slots().safe_sub(E::slots_per_epoch() as usize)?;
   493→    for (i, proposer) in last_epoch_proposers.into_iter().enumerate() {
   494→        let index = last_epoch_start.safe_add(i)?;
   495→        *lookahead
   496→            .get_mut(index)
   497→            .ok_or(Error::ProposerLookaheadOutOfBounds(index))? = proposer as u64;
   498→    }
